1	import * as THREE from "three";
2	import { SceneObject } from "../../core/SceneObject.js";
3	import { rocket } from "../../core/setup.js";
4	import type {
5	  CloudPlaneTweenProps,
6	  SharedCloudTextureEntry,
7	} from "../../types/object.types.js";
8	import type {
9	  CloudPlaneObjectOptions,
10	  ResolvedBackgroundPlaneOptions,
11	} from "../../types/object-visual.types.js";
12	import type { ShaderUniformRecord } from "../../types/object-runtime.types.js";
13	import cloudPlaneFragmentShader from "../../../shaders/cloud-plane/cloud-plane.fragment.glsl?raw";
14	import cloudPlaneVertexShader from "../../../shaders/cloud-plane/cloud-plane.vertex.glsl?raw";
15	
16	const CLOUD_PLANE_RENDER_ORDER = -1190;
17	const CLOUD_PLANE_WIDTH = 100;
18	const CLOUD_PLANE_HEIGHT = 100;
19	const CLOUD_PLANE_SEGMENTS = 1;
20	const CLOUD_PLANE_CURVE_DEPTH = 0;
21	const CLOUD_PLANE_CURVE_POWER = 1;
22	const DEFAULT_CLOUD_DARK_COLOR = 0xa7b9cf;
23	const DEFAULT_CLOUD_LIGHT_COLOR = 0xf3f8ff;
24	const CLOUD_MOUSE_TEXTURE_SIZE = 256;
25	const CLOUD_MOUSE_TEXTURE_CHANNELS = 4;
26	const CLOUD_MOUSE_TEXTURE_FADE = 0.9;
27	const CLOUD_ROCKET_EFFECT_DEPTH = 12;
28	const CLOUD_ROCKET_EFFECT_RADIUS = 0.2;
29	
30	export class CloudPlane extends SceneObject<CloudPlaneTweenProps> {
31	  private static readonly _sharedTextures = new Map<
32	    string,
33	    SharedCloudTextureEntry
34	  >();
35	  private _options: Partial<CloudPlaneObjectOptions> = {};
36	  private _mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial> | null =
37	    null;
38	  private _material: THREE.ShaderMaterial | null = null;
39	  private _perlinTexture: THREE.Texture | null = null;
40	  private _noiseTexture: THREE.Texture | null = null;
41	  private _mouseTexture: THREE.Texture | null = null;
42	  private readonly _sharedTextureKeys = new Set<string>();
43	  private _mouseTextureData: Float32Array | null = null;
44	  private _elapsedTime = 0;
45	  private readonly _rocketWorldPosition = new THREE.Vector3();
46	  private readonly _rocketLocalPosition = new THREE.Vector3();
47	  private readonly _rocketUvFallback = new THREE.Vector2();
48	  private _resolvedPlaneOptions: ResolvedBackgroundPlaneOptions = {
49	    size: CLOUD_PLANE_WIDTH,
50	    width: CLOUD_PLANE_WIDTH,
51	    height: CLOUD_PLANE_HEIGHT,
52	    segments: CLOUD_PLANE_SEGMENTS,
53	    curveDepth: CLOUD_PLANE_CURVE_DEPTH,
54	    curvePower: CLOUD_PLANE_CURVE_POWER,
55	  };
56	
57	  setOptions(props: Partial<CloudPlaneObjectOptions> | undefined): this {
58	    if (props) this._options = { ...this._options, ...props };
59	    this._refreshResolvedPlaneOptions();
60	    return this;
61	  }
62	
63	  protected override getOptions(): Record<string, unknown> {
64	    return this._options;
65	  }
66	
67	  protected override mergeOptionsFromTimeline(
68	    vars: Partial<CloudPlaneTweenProps>,
69	  ): void {
70	    const next = this._options;
71	    if (vars.position) next.position = { ...next.position, ...vars.position };
72	    if (vars.rotation) next.rotation = { ...next.rotation, ...vars.rotation };
73	    if (vars.scale) next.scale = { ...next.scale, ...vars.scale };
74	    const visible = vars.visible;
75	    const chapter = vars.chapter;
76	    const transition = vars.transition;
77	    if (typeof visible === "boolean") next.visible = visible;
78	    if (typeof chapter === "number") next.chapter = chapter;
79	    if (typeof transition === "number") next.transition = transition;
80	  }
81	
82	  override getBloomEnabled(): boolean {
83	    return false;
84	  }
85	
86	  override getAnimationTarget(): THREE.Object3D | null {
87	    return this.getTimelineRoot();
88	  }
89	
90	  protected override applyVisibility(visible: boolean): void {
91	    const root = this.getTimelineRoot();
92	    if (root) root.visible = visible;
93	  }
94	
95	  protected override syncFromOptions(): void {
96	    this._applyBaseTransform();
97	    this._applyStaticUniforms();
98	  }
99	
100	  override async runObject(): Promise<void> {
101	    const scene = this._context?.scene;
102	    if (!scene) return;
103	
104	    const root = this.ensureTimelineRoot(this._getLayerLabel());
105	    if (!root) return;
106	    root.name = this._getLayerLabel();
107	
108	    this._clearRuntime();
109	    await this._prepareShaderTextures();
110	
111	    this._material = this._createMaterial();
112	    this._mesh = new THREE.Mesh(
113	      this._createCurvedPlaneGeometry(),
114	      this._material,
115	    );
116	    this._mesh.name = `${this._getLayerLabel()}.mesh`;
117	    this._mesh.frustumCulled = false;
118	    this._mesh.renderOrder = CLOUD_PLANE_RENDER_ORDER;
119	    root.add(this._mesh);
120	
121	    this._applyBaseTransform();
122	    this._applyStaticUniforms();
123	    this._applyDynamicUniforms();
124	  }
125	
126	  override runUpdate(deltaTime: number): void {
127	    this._elapsedTime += Number.isFinite(deltaTime)
128	      ? Math.max(0, deltaTime)
129	      : 0;
130	    this._updateMouseTexture();
131	    this._applyDynamicUniforms();
132	  }
133	
134	  override dispose(): void {
135	    this._clearRuntime();
136	    super.dispose();
137	  }
138	
139	  private async _prepareShaderTextures(): Promise<void> {
140	    this._disposeTextures();
141	    const ctx = this._context;
142	    const textures = this._options.shader?.textures;
143	    if (!ctx?.loadTexture || !textures) return;
144	    const perlinTextureUrl = textures.perlinTextureUrl?.trim();
145	    const noiseTextureUrl = textures.noiseTextureUrl?.trim();
146	    if (!perlinTextureUrl || !noiseTextureUrl) return;
147	    const [perlinTexture, noiseTexture] = await Promise.all([
148	      this._loadSharedTexture(
149	        this.resolveAssetPath(perlinTextureUrl),
150	        this._prepareRepeatTexture,
151	      ),
152	      this._loadSharedTexture(
153	        this.resolveAssetPath(noiseTextureUrl),
154	        this._prepareRepeatTexture,
155	      ),
156	    ]);
157	    this._perlinTexture = perlinTexture;
158	    this._noiseTexture = noiseTexture;
159	    this._createMouseTexture();
160	    const perlinTextureRef = this._perlinTexture;
161	    const noiseTextureRef = this._noiseTexture;
162	    const mouseTextureRef = this._mouseTexture;
163	    if (perlinTextureRef) ctx.prepareTexture?.(perlinTextureRef);
164	    if (noiseTextureRef) ctx.prepareTexture?.(noiseTextureRef);
165	    if (mouseTextureRef) ctx.prepareTexture?.(mouseTextureRef);
166	  }
167	
168	  private _prepareRepeatTexture(texture: THREE.Texture): THREE.Texture {
169	    texture.wrapS = THREE.RepeatWrapping;
170	    texture.wrapT = THREE.RepeatWrapping;
171	    texture.magFilter = THREE.LinearFilter;
172	    texture.minFilter = THREE.LinearMipmapLinearFilter;
173	    texture.needsUpdate = true;
174	    return texture;
175	  }
176	
177	  private _createMaterial(): THREE.ShaderMaterial {
178	    const shader = this._options.shader;
179	    return new THREE.ShaderMaterial({
180	      uniforms: {
181	        uTime: { value: 0 },
182	        uRatio: { value: this._finiteOr(shader?.ratio, 2) },
183	        uChapter: {
184	          value: this._finiteOr(
185	            shader?.chapter,
186	            this._finiteOr(this._options.chapter, 0),
187	          ),
188	        },
189	        uTransition: {
190	          value: this._finiteOr(
191	            shader?.transition,
192	            this._finiteOr(this._options.transition, 0),
193	          ),
194	        },
195	        uOpacity: { value: this._finiteOr(shader?.opacity, 0.16) },
196	        uRocketInfluence: { value: 0 },
197	        uRocketRadius: { value: CLOUD_ROCKET_EFFECT_RADIUS },
198	        uRocketUv: { value: new THREE.Vector2(0.5, 0.5) },
199	        uDarkColor: { value: new THREE.Color(DEFAULT_CLOUD_DARK_COLOR) },
200	        uLightColor: { value: new THREE.Color(DEFAULT_CLOUD_LIGHT_COLOR) },
201	        uSize: {
202	          value: new THREE.Vector2(
203	            this._finiteOr(shader?.size?.x, 1),
204	            this._finiteOr(shader?.size?.y, 1),
205	          ),
206	        },
207	        uResolution: { value: new THREE.Vector2(1, 1) },
208	        tPerlin: { value: this._perlinTexture },
209	        tNoise: { value: this._noiseTexture },
210	        tMouse: { value: this._mouseTexture },
211	      },
212	      vertexShader: cloudPlaneVertexShader,
213	      fragmentShader: cloudPlaneFragmentShader,
214	      side: THREE.DoubleSide,
215	      transparent: true,
216	      depthWrite: false,
217	      depthTest: false,
218	      fog: false,
219	    });
220	  }
221	
222	  private _applyBaseTransform(): void {
223	    const root = this.getTimelineRoot();
224	    if (!root) return;
225	    root.name = this._getLayerLabel();
226	    root.position.set(
227	      this._options.position?.x ?? 0,
228	      this._options.position?.y ?? 0,
229	      this._options.position?.z ?? 0,
230	    );
231	    root.rotation.set(
232	      THREE.MathUtils.degToRad(this._options.rotation?.x ?? 0),
233	      THREE.MathUtils.degToRad(this._options.rotation?.y ?? 0),
234	      THREE.MathUtils.degToRad(this._options.rotation?.z ?? 0),
235	    );
236	    root.scale.set(
237	      this._options.scale?.x ?? 1,
238	      this._options.scale?.y ?? 1,
239	      this._options.scale?.z ?? 1,
240	    );
241	  }
242	
243	  private _applyStaticUniforms(): void {
244	    const uniforms = this._material?.uniforms as
245	      | ShaderUniformRecord
246	      | undefined;
247	    if (!uniforms) return;
248	    this._setUniformNumber(
249	      uniforms,
250	      "uChapter",
251	      this._finiteOr(
252	        this._options.chapter,
253	        this._finiteOr(this._options.shader?.chapter, 0),
254	      ),
255	    );
256	    this._setUniformNumber(
257	      uniforms,
258	      "uTransition",
259	      this._finiteOr(
260	        this._options.transition,
261	        this._finiteOr(this._options.shader?.transition, 0),
262	      ),
263	    );
264	  }
265	
266	  private _applyDynamicUniforms(): void {
267	    const uniforms = this._material?.uniforms as
268	      | ShaderUniformRecord
269	      | undefined;
270	    if (!uniforms) return;
271	    this._setUniformNumber(uniforms, "uTime", this._elapsedTime);
272	    this._applyResolutionUniform(uniforms);
273	    this._applyRocketUniforms(uniforms);
274	  }
275	
276	  private _applyResolutionUniform(uniforms: ShaderUniformRecord): void {
277	    const target = uniforms.uResolution;
278	    if (!target) return;
279	    const renderer = this._context?.renderer;
280	    const width = renderer?.domElement?.width;
281	    const height = renderer?.domElement?.height;
282	    if (
283	      !(target.value instanceof THREE.Vector2) ||
284	      !Number.isFinite(width) ||
285	      !Number.isFinite(height)
286	    ) {
287	      return;
288	    }
289	    target.value.set(width as number, height as number);
290	  }
291	
292	  private _applyRocketUniforms(uniforms: ShaderUniformRecord): void {
293	    const root = this.getTimelineRoot();
294	    const rocketObject = this._context?.getObject(rocket) as
295	      | THREE.Object3D
296	      | null;
297	    const rocketInfluence = uniforms.uRocketInfluence;
298	    const rocketUv = uniforms.uRocketUv;
299	    if (!root || !rocketObject || !rocketInfluence || !rocketUv) {
300	      if (rocketInfluence) rocketInfluence.value = 0;
301	      return;
302	    }
303	
304	    rocketObject.updateWorldMatrix(true, false);
305	    rocketObject.getWorldPosition(this._rocketWorldPosition);
306	    root.updateWorldMatrix(true, false);
307	    this._rocketLocalPosition.copy(this._rocketWorldPosition);
308	    root.worldToLocal(this._rocketLocalPosition);
309	
310	    const plane = this._resolvePlaneOptions();
311	    const halfWidth = plane.width * 0.5;
312	    const halfHeight = plane.height * 0.5;
313	    const normalizedX = this._rocketLocalPosition.x / Math.max(halfWidth, 0.0001);
314	    const normalizedY = this._rocketLocalPosition.y / Math.max(halfHeight, 0.0001);
315	    const lateralDistance = Math.max(Math.abs(normalizedX), Math.abs(normalizedY));
316	    const depthDistance = Math.abs(this._rocketLocalPosition.z);
317	    const lateralInfluence = 1 - this._smoothstep(0.35, 1.2, lateralDistance);
318	    const depthInfluence =
319	      1 -
320	      this._smoothstep(
321	        CLOUD_ROCKET_EFFECT_DEPTH * 0.2,
322	        CLOUD_ROCKET_EFFECT_DEPTH,
323	        depthDistance,
324	      );
325	    rocketInfluence.value = lateralInfluence * depthInfluence;
326	    const rocketUvValue =
327	      rocketUv.value instanceof THREE.Vector2
328	        ? rocketUv.value
329	        : this._rocketUvFallback;
330	    rocketUvValue.set(normalizedX * 0.5 + 0.5, normalizedY * 0.5 + 0.5);
331	    rocketUv.value = rocketUvValue;
332	  }
333	
334	  private _createCurvedPlaneGeometry(): THREE.PlaneGeometry {
335	    const plane = this._resolvePlaneOptions();
336	    const geometry = new THREE.PlaneGeometry(
337	      plane.width,
338	      plane.height,
339	      plane.segments,
340	      plane.segments,
341	    );
342	    if (plane.curveDepth <= 0 || plane.segments <= 1) {
343	      geometry.computeVertexNormals();
344	      geometry.computeBoundingSphere();
345	      return geometry;
346	    }
347	    const position = geometry.getAttribute("position");
348	    for (let index = 0; index < position.count; index += 1) {
349	      const x = position.getX(index);
350	      const y = position.getY(index);
351	      const normalizedX = Math.abs(x / (plane.width * 0.5));
352	      const normalizedY = Math.abs(y / (plane.height * 0.5));
353	      const clampedX = THREE.MathUtils.clamp(normalizedX, 0, 1);
354	      const clampedY = THREE.MathUtils.clamp(normalizedY, 0, 1);
355	      const edgeCurve = this._smoothstep(
356	        0.72,
357	        1,
358	        Math.pow(clampedX, plane.curvePower),
359	      );
360	      const horizontalCurve =
361	        (1 - Math.cos(edgeCurve * Math.PI * 0.5)) * edgeCurve;
362	      const verticalCurve = 1 - Math.pow(clampedY, 1.5) * 0.03;
363	      position.setZ(
364	        index,
365	        plane.curveDepth *
366	          horizontalCurve *
367	          THREE.MathUtils.clamp(verticalCurve, 0.96, 1),
368	      );
369	    }
370	    position.needsUpdate = true;
371	    geometry.computeVertexNormals();
372	    geometry.computeBoundingSphere();
373	    return geometry;
374	  }
375	
376	  private _resolvePlaneOptions(): ResolvedBackgroundPlaneOptions {
377	    return this._resolvedPlaneOptions;
378	  }
379	
380	  private _refreshResolvedPlaneOptions(): void {
381	    const plane = this._options.plane;
382	    const fallbackSize = this._resolvePositiveNumber(
383	      plane?.size,
384	      CLOUD_PLANE_WIDTH,
385	    );
386	    const cache = this._resolvedPlaneOptions;
387	    cache.size = fallbackSize;
388	    cache.width = this._resolvePositiveNumber(plane?.width, fallbackSize);
389	    cache.height = this._resolvePositiveNumber(plane?.height, CLOUD_PLANE_HEIGHT);
390	    cache.segments = Math.max(
391	      1,
392	      Math.round(
393	        this._resolvePositiveNumber(plane?.segments, CLOUD_PLANE_SEGMENTS),
394	      ),
395	    );
396	    cache.curveDepth = this._resolvePositiveNumber(
397	      plane?.curveDepth,
398	      CLOUD_PLANE_CURVE_DEPTH,
399	    );
400	    cache.curvePower = this._resolvePositiveNumber(
401	      plane?.curvePower,
402	      CLOUD_PLANE_CURVE_POWER,
403	    );
404	  }
405	
406	  private _smoothstep(edge0: number, edge1: number, value: number): number {
407	    const normalized = THREE.MathUtils.clamp(
408	      (value - edge0) / Math.max(edge1 - edge0, Number.EPSILON),
409	      0,
410	      1,
411	    );
412	    return normalized * normalized * (3 - 2 * normalized);
413	  }
414	
415	  private _clearRuntime(): void {
416	    if (this._mesh) {
417	      this._mesh.geometry.dispose();
418	      this._mesh.material.dispose();
419	      this._mesh.parent?.remove(this._mesh);
420	    }
421	    this._mesh = null;
422	    this._material = null;
423	    this._disposeTextures();
424	    this._elapsedTime = 0;
425	  }
426	
427	  private _disposeTextures(): void {
428	    for (const key of this._sharedTextureKeys) {
429	      const cached = CloudPlane._sharedTextures.get(key);
430	      if (!cached) continue;
431	      cached.refs -= 1;
432	      if (cached.refs <= 0) {
433	        cached.texture.dispose();
434	        CloudPlane._sharedTextures.delete(key);
435	      }
436	    }
437	    this._sharedTextureKeys.clear();
438	    this._mouseTexture?.dispose();
439	    this._perlinTexture = null;
440	    this._noiseTexture = null;
441	    this._mouseTexture = null;
442	    this._mouseTextureData = null;
443	  }
444	
445	  private async _loadSharedTexture(
446	    url: string,
447	    prepare: (texture: THREE.Texture) => THREE.Texture,
448	  ): Promise<THREE.Texture> {
449	    const cached = CloudPlane._sharedTextures.get(url);
450	    if (cached) {
451	      cached.refs += 1;
452	      this._sharedTextureKeys.add(url);
453	      return cached.texture;
454	    }
455	    const loader = this._context?.loadTexture;
456	    if (!loader) {
457	      throw new Error(`Cloud texture loader is unavailable for ${url}`);
458	    }
459	    const texture = prepare.call(this, await loader(url));
460	    CloudPlane._sharedTextures.set(url, {
461	      texture,
462	      refs: 1,
463	    });
464	    this._sharedTextureKeys.add(url);
465	    return texture;
466	  }
467	
468	  private _getLayerLabel(): string {
469	    const label = this._options.label?.trim();
470	    return label && label.length > 0 ? label : "cloudPlaneRoot";
471	  }
472	
473	  private _createMouseTexture(): void {
474	    this._mouseTextureData = new Float32Array(
475	      CLOUD_MOUSE_TEXTURE_SIZE *
476	        CLOUD_MOUSE_TEXTURE_SIZE *
477	        CLOUD_MOUSE_TEXTURE_CHANNELS,
478	    );
479	    this._mouseTexture = new THREE.DataTexture(
480	      this._mouseTextureData,
481	      CLOUD_MOUSE_TEXTURE_SIZE,
482	      CLOUD_MOUSE_TEXTURE_SIZE,
483	      THREE.RGBAFormat,
484	      THREE.FloatType,
485	    );
486	    this._mouseTexture.wrapS = THREE.ClampToEdgeWrapping;
487	    this._mouseTexture.wrapT = THREE.ClampToEdgeWrapping;
488	    this._mouseTexture.magFilter = THREE.LinearFilter;
489	    this._mouseTexture.minFilter = THREE.LinearFilter;
490	    this._mouseTexture.generateMipmaps = false;
491	    this._mouseTexture.needsUpdate = true;
492	  }
493	
494	  private _updateMouseTexture(): void {
495	    const mouseTexture = this._mouseTexture;
496	    const mouseTextureData = this._mouseTextureData;
497	    if (!mouseTexture || !mouseTextureData) return;
498	    for (
499	      let index = 0;
500	      index < mouseTextureData.length;
501	      index += CLOUD_MOUSE_TEXTURE_CHANNELS
502	    ) {
503	      mouseTextureData[index] *= CLOUD_MOUSE_TEXTURE_FADE;
504	      mouseTextureData[index + 1] *= CLOUD_MOUSE_TEXTURE_FADE;
505	      mouseTextureData[index + 2] *= CLOUD_MOUSE_TEXTURE_FADE;
506	      mouseTextureData[index + 3] = 1;
507	    }
508	    mouseTexture.needsUpdate = true;
509	  }
510	
511	  private _setUniformNumber(
512	    uniforms: ShaderUniformRecord,
513	    key: string,
514	    value: number,
515	  ): void {
516	    const target = uniforms[key];
517	    if (!target) return;
518	    target.value = value;
519	  }
520	
521	  private _finiteOr(value: unknown, fallback: number): number {
522	    return Number.isFinite(value as number) ? (value as number) : fallback;
523	  }
524	
525	  private _resolvePositiveNumber(value: unknown, fallback: number): number {
526	    if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
527	      return fallback;
528	    }
529	    return value;
530	  }
531	}
