1	import * as THREE from "three";
2	import { SceneObject } from "../../core/SceneObject.js";
3	import type {
4	  EarthObjectOptions,
5	  EarthTweenProps,
6	} from "../../types/object.types.js";
7	import type { EarthResolvedOptions } from "../../types/object-runtime.types.js";
8	import { Helpers } from "../../utils/Helpers.js";
9	import atmosphereVertexShader from "../../../shaders/earth/vertex.glsl?raw";
10	import atmosphereFragmentShader from "../../../shaders/earth/fragment.glsl?raw";
11	import earthPatchCommonShader from "../../../shaders/earth/patch-common.glsl?raw";
12	import earthPatchRoughnessShader from "../../../shaders/earth/patch-roughnessmap.glsl?raw";
13	import earthPatchEmissiveShader from "../../../shaders/earth/patch-emissivemap.glsl?raw";
14	import earthPatchOutputShader from "../../../shaders/earth/patch-output.glsl?raw";
15	import { THREE_LAYER_EARTH } from "../../core/setup.js";
16	
17	export class Earth extends SceneObject<EarthTweenProps> {
18	  private _options: Partial<EarthObjectOptions> = {};
19	  private _earthGroup: THREE.Group | null = null;
20	  private _earthGeometry: THREE.SphereGeometry | null = null;
21	  private _cloudGeometry: THREE.SphereGeometry | null = null;
22	  private _atmosphereGeometry: THREE.SphereGeometry | null = null;
23	  private _earthMesh: THREE.Mesh<
24	    THREE.SphereGeometry,
25	    THREE.MeshStandardMaterial
26	  > | null = null;
27	  private _cloudMesh: THREE.Mesh<
28	    THREE.SphereGeometry,
29	    THREE.MeshStandardMaterial
30	  > | null = null;
31	  private _atmosphereMesh: THREE.Mesh<
32	    THREE.SphereGeometry,
33	    THREE.ShaderMaterial
34	  > | null = null;
