336	  private _patchEarthMaterialShader(
337	    earthMaterial: THREE.MeshStandardMaterial,
338	    cloudsMap: THREE.Texture,
339	  ): void {
340	    earthMaterial.onBeforeCompile = (shader) => {
341	      shader.uniforms.tClouds = { value: cloudsMap };
342	      shader.uniforms.uv_xOffset = { value: 0 };
343	      shader.uniforms.uNightFloor = this._shadingUniforms.uNightFloor;
344	      shader.uniforms.uTerminatorSoftness =
345	        this._shadingUniforms.uTerminatorSoftness;
346	      shader.uniforms.uCloudShadowStrength =
347	        this._shadingUniforms.uCloudShadowStrength;
348	      shader.fragmentShader = shader.fragmentShader.replace(
349	        "#include <common>",
350	        earthPatchCommonShader,
351	      );
352	      shader.fragmentShader = shader.fragmentShader.replace(
353	        "#include <roughnessmap_fragment>",
354	        earthPatchRoughnessShader,
355	      );
356	      shader.fragmentShader = shader.fragmentShader.replace(
357	        "#include <emissivemap_fragment>",
358	        earthPatchEmissiveShader,
359	      );
360	
361	      shader.fragmentShader = shader.fragmentShader.replace(
362	        "#include <output_fragment>",
363	        earthPatchOutputShader,
364	      );
365	      earthMaterial.userData.shader = shader;
366	    };
367	    earthMaterial.needsUpdate = true;
368	  }
