370	  private _syncEarthShaderUniforms(): void {
371	    const shader = this._earthMaterial?.userData?.shader as
372	      | {
373	          uniforms?: Record<string, { value: number }>;
374	        }
375	      | undefined;
376	    const uniforms = shader?.uniforms;
377	    if (!uniforms) return;
378	    if (uniforms.uNightFloor) {
379	      uniforms.uNightFloor.value = this._shadingUniforms.uNightFloor.value;
380	    }
381	    if (uniforms.uTerminatorSoftness) {
382	      uniforms.uTerminatorSoftness.value =
383	        this._shadingUniforms.uTerminatorSoftness.value;
384	    }
385	    if (uniforms.uCloudShadowStrength) {
386	      uniforms.uCloudShadowStrength.value =
387	        this._shadingUniforms.uCloudShadowStrength.value;
388	    }
389	  }
390	
391	  private _updateCloudShadowOffset(earthRotationStep: number): void {
392	    const shader = this._earthMaterial?.userData?.shader as
393	      | {
394	          uniforms?: Record<string, { value: unknown }>;
395	        }
396	      | undefined;
397	    const uniforms = shader?.uniforms;
398	    const uvOffset = uniforms?.uv_xOffset as { value: number } | undefined;
399	    if (!uvOffset) return;
400	    const offset = earthRotationStep / (2 * Math.PI);
401	    uvOffset.value = (uvOffset.value + offset) % 1;
402	    if (uvOffset.value < 0) uvOffset.value += 1;
403	  }
404	
405	  private _applyEarthLayer(root: THREE.Object3D): void {
406	    root.traverse((node) => {
407	      node.layers.set(THREE_LAYER_EARTH);
408	    });
409	  }
410	
411	  private _prepareTextures(textures: THREE.Texture[]): void {
412	    const prepareTexture = this._context?.prepareTexture;
413	    if (!prepareTexture) return;
414	    textures.forEach((texture) => prepareTexture(texture));
415	  }
416	
417	  private _prewarmSceneCompile(root: THREE.Object3D): void {
418	    if (this._didPrewarm) return;
419	    const compileScene = this._context?.compileScene;
420	    if (!compileScene) return;
421	    const previousVisible = root.visible;
422	    root.visible = true;
423	    compileScene();
424	    root.visible = previousVisible;
425	    this._didPrewarm = true;
426	  }
