306	  private _applyRuntimeUniforms(): void {
307	    const uniforms = this._material?.uniforms as ShaderUniformRecord | undefined;
308	    if (!uniforms) return;
309	    const isActive = this._runtimeState.active ?? false;
310	    const progress = Helpers.clamp01(
311	      this._runtimeState.progress ?? this._options.progress ?? 0,
312	    );
313	    if (
314	      isActive ||
315	      this._lastActive !== isActive ||
316	      Math.abs(progress - this._lastProgress) > TRANSITION_VEIL_PROGRESS_EPSILON
317	    ) {
318	      this._setUniformNumber(uniforms, "uProgress", progress);
319	      this._lastProgress = progress;
320	    }
321	    if (
322	      isActive &&
323	      Math.abs(this._elapsedTime - this._lastTimeUniform) > TRANSITION_VEIL_TIME_EPSILON
324	    ) {
325	      this._setUniformNumber(uniforms, "uTime", this._elapsedTime);
326	      this._lastTimeUniform = this._elapsedTime;
327	    }
328	    const resolution = uniforms.uResolution?.value;
329	    const renderer = this._context?.renderer;
330	    const width = renderer?.domElement?.width;
331	    const height = renderer?.domElement?.height;
332	    if (!(resolution instanceof THREE.Vector2)) return;
333	    if (!Number.isFinite(width) || !Number.isFinite(height)) return;
334	    const nextWidth = width as number;
335	    const nextHeight = height as number;
336	    if (
337	      nextWidth !== this._lastResolutionWidth ||
338	      nextHeight !== this._lastResolutionHeight
339	    ) {
340	      resolution.set(nextWidth, nextHeight);
341	      this._lastResolutionWidth = nextWidth;
342	      this._lastResolutionHeight = nextHeight;
