1	import * as THREE from "three";
2	import { SceneObject } from "../../core/SceneObject.js";
3	import type {
4	  PlanetObjectOptions,
5	  PlanetTweenProps,
6	} from "../../types/object.types.js";
7	import type { PlanetResolvedOptions } from "../../types/object-runtime.types.js";
8	import { Helpers } from "../../utils/Helpers.js";
9	import atmosphereVertexShader from "../../../shaders/earth/vertex.glsl?raw";
10	
11	const PLANET_ATMOSPHERE_FRAGMENT_SHADER = `
12	varying vec3 vNormal;
13	varying vec3 eyeVector;
14	uniform float atmOpacity;
15	uniform float atmPowFactor;
16	uniform float atmMultiplier;
17	uniform vec3 atmColor;
18	
19	void main() {
20	    float dotP = max(0.0, dot(vNormal, eyeVector));
21	    float factor = pow(dotP, atmPowFactor) * atmMultiplier;
22	    vec3 rimColor = mix(atmColor * 0.82, vec3(1.0), 0.28 + dotP * 0.18);
23	    gl_FragColor = vec4(rimColor, atmOpacity) * factor;
24	}
25	`;
26	
27	export class Planet extends SceneObject<PlanetTweenProps> {
28	  private _options: Partial<PlanetObjectOptions> = {};
29	  private _geometry: THREE.SphereGeometry | null = null;
30	  private _atmosphereGeometry: THREE.SphereGeometry | null = null;
31	  private _material: THREE.MeshStandardMaterial | null = null;
32	  private _atmosphereMaterial: THREE.ShaderMaterial | null = null;
33	  private _mesh: THREE.Mesh<
34	    THREE.SphereGeometry,
35	    THREE.MeshStandardMaterial
36	  > | null = null;
37	  private _atmosphereMesh: THREE.Mesh<
38	    THREE.SphereGeometry,
39	    THREE.ShaderMaterial
40	  > | null = null;
41	  private _group: THREE.Group | null = null;
42	  private _textures: THREE.Texture[] = [];
43	  private _materials: THREE.Material[] = [];
44	  private _didPrewarm = false;
45	  private readonly _atmosphereUniforms = {
46	    atmOpacity: { value: 0.42 },
47	    atmPowFactor: { value: 4.8 },
48	    atmMultiplier: { value: 5.8 },
49	    atmColor: { value: new THREE.Color(1, 1, 1) },
50	  };
51	
52	  setOptions(props: Partial<PlanetObjectOptions> | undefined): this {
53	    if (props != null) this._assignOptions(props);
54	    return this;
55	  }
56	
57	  override getAnimationTarget(): THREE.Object3D | null {
58	    return this.getTimelineRoot();
59	  }
60	
61	  override getTweenApplyMode(): "mergeAndSync" {
62	    return "mergeAndSync";
63	  }
64	
65	  protected override getOptions(): Record<string, unknown> {
66	    return this._options as Record<string, unknown>;
67	  }
68	
69	  protected override applyVisibility(visible: boolean): void {
70	    const root = this.getTimelineRoot();
71	    if (!root) return;
72	    root.visible = visible;
73	  }
74	
75	  protected override syncFromOptions(): void {
76	    const options = this._resolveOptions();
77	    const root = this.getTimelineRoot();
78	    if (root) {
79	      Helpers.applyTransform(root, options);
80	      root.visible = options.visible;
81	    }
82	    if (this._material) {
83	      this._material.color.setHex(options.color);
84	      this._material.roughness = options.roughness;
85	      this._material.metalness = options.metalness;
86	      this._material.bumpScale = options.bumpScale;
87	    }
88	    this._atmosphereUniforms.atmOpacity.value = options.atmosphereOpacity;
89	    this._atmosphereUniforms.atmPowFactor.value = options.atmospherePowFactor;
90	    this._atmosphereUniforms.atmMultiplier.value = options.atmosphereMultiplier;
91	    this._atmosphereUniforms.atmColor.value.setRGB(
92	      options.atmosphereColor[0],
93	      options.atmosphereColor[1],
94	      options.atmosphereColor[2],
95	    );
96	  }
97	
98	  override async runObject(): Promise<void> {
99	    const options = this._resolveOptions();
100	    const texturePaths = this._resolveTexturePaths(options);
101	    const [dayMap, bumpMap] = await Promise.all([
102	      this._loadTexture(texturePaths.dayTextureUrl, true),
103	      this._loadTexture(texturePaths.bumpTextureUrl, false),
104	    ]);
105	    this._prepareTextures([dayMap, bumpMap]);
106	    this._textures.push(dayMap, bumpMap);
107	
108	    this._geometry = new THREE.SphereGeometry(
109	      options.radius,
110	      options.widthSegments,
111	      options.heightSegments,
112	    );
113	    this._material = new THREE.MeshStandardMaterial({
114	      color: options.color,
115	      map: dayMap,
116	      bumpMap,
117	      bumpScale: options.bumpScale,
118	      roughness: options.roughness,
119	      metalness: options.metalness,
120	    });
121	    this._materials.push(this._material);
122	    this._mesh = new THREE.Mesh(this._geometry, this._material);
123	    this._mesh.name = "planetMesh";
124	
125	    this._atmosphereGeometry = new THREE.SphereGeometry(
126	      options.radius * options.atmosphereScale,
127	      options.widthSegments,
128	      options.heightSegments,
129	    );
130	    this._atmosphereMaterial = new THREE.ShaderMaterial({
131	      vertexShader: atmosphereVertexShader as string,
132	      fragmentShader: PLANET_ATMOSPHERE_FRAGMENT_SHADER,
133	      uniforms: this._atmosphereUniforms,
134	      blending: THREE.AdditiveBlending,
135	      side: THREE.BackSide,
136	      transparent: true,
137	      depthWrite: false,
138	    });
139	    this._materials.push(this._atmosphereMaterial);
140	    this._atmosphereMesh = new THREE.Mesh(
141	      this._atmosphereGeometry,
142	      this._atmosphereMaterial,
143	    );
144	    this._atmosphereMesh.name = "planetAtmosphereMesh";
