146	    this._group = new THREE.Group();
147	    this._group.name = "planetGroup";
148	    this._group.add(this._mesh);
149	    this._group.add(this._atmosphereMesh);
150	
151	    this.attachToTimelineRoot(this._group, "planetRoot");
152	    this.syncFromOptions();
153	    const root = this.getTimelineRoot();
154	    if (!root) return;
155	    this._prewarmSceneCompile(root);
156	  }
