160	  override dispose(): void {
161	    this._geometry?.dispose();
162	    this._atmosphereGeometry?.dispose();
163	    this._materials.forEach((material) => material.dispose());
164	    this._textures.forEach((texture) => texture.dispose());
165	    this._geometry = null;
166	    this._atmosphereGeometry = null;
167	    this._material = null;
168	    this._atmosphereMaterial = null;
169	    this._mesh = null;
170	    this._atmosphereMesh = null;
171	    this._group = null;
172	    this._materials = [];
173	    this._textures = [];
174	    this._didPrewarm = false;
175	    super.dispose();
176	  }
