178	  private _assignOptions(props: Partial<PlanetObjectOptions>): void {
179	    const next: Partial<PlanetObjectOptions> = {
180	      ...this._options,
181	      ...props,
182	    };
183	    if (props.position) next.position = { ...props.position };
184	    if (props.rotation) next.rotation = { ...props.rotation };
185	    if (props.scale) next.scale = { ...props.scale };
186	    if (props.effects) next.effects = { ...props.effects };
187	    this._options = next;
