190	  private _resolveOptions(): PlanetResolvedOptions {
191	    const options = this._options;
192	    return {
193	      radius: options.radius ?? 1,
194	      widthSegments: options.widthSegments ?? 32,
195	      heightSegments: options.heightSegments ?? 24,
196	      color: options.color ?? 0xffffff,
197	      dayTextureUrl: options.dayTextureUrl ?? "",
198	      bumpTextureUrl: options.bumpTextureUrl ?? "",
199	      bumpScale: options.bumpScale ?? 0.018,
200	      roughness: options.roughness ?? 0.42,
201	      metalness: options.metalness ?? 0.05,
