204	  private _renderSelective(
205	    bloomRoots: Set<THREE.Object3D>,
206	    hasRoots: boolean,
207	    deltaTime?: number,
208	  ): void {
209	    if (
210	      !this._selective ||
211	      !this._bloomComposer ||
212	      !this._finalComposer ||
213	      !this._darkMaterial
214	    ) {
215	      this._composer?.render(deltaTime);
216	      return;
217	    }
218	    if (hasRoots !== this._lastHasRoots) {
219	      this._lastHasRoots = hasRoots;
