304	  private _normalizeBloomOptions(
305	    bloomOpt: PostProcessorOptions["bloom"],
306	  ): Required<Omit<BloomOptions, "selective">> & { selective: boolean } {
307	    if (typeof bloomOpt !== "object" || bloomOpt == null) {
308	      return { ...DEFAULT_BLOOM };
309	    }
310	    const strength = this._clampFinite(
311	      bloomOpt.strength,
312	      DEFAULT_BLOOM.strength,
313	      0,
314	      5,
315	    );
316	    const radius = this._clampFinite(
317	      bloomOpt.radius,
318	      DEFAULT_BLOOM.radius,
319	      0,
320	      2,
321	    );
322	    const threshold = this._clampFinite(
323	      bloomOpt.threshold,
324	      DEFAULT_BLOOM.threshold,
325	      0,
326	      2,
327	    );
328	    const compositeStrength = this._clampFinite(
329	      bloomOpt.compositeStrength,
330	      DEFAULT_BLOOM.compositeStrength,
331	      0,
332	      1,
333	    );
334	    const selective =
335	      typeof bloomOpt.selective === "boolean"
336	        ? bloomOpt.selective
337	        : DEFAULT_BLOOM.selective;
338	    return { strength, radius, threshold, compositeStrength, selective };
339	  }
