341	  private _normalizeVignetteOptions(
342	    vignetteOpt: PostProcessorOptions["vignette"],
343	  ): Required<VignetteOptions> | null {
344	    if (vignetteOpt === false || vignetteOpt == null) return null;
345	    if (vignetteOpt === true) return { ...DEFAULT_VIGNETTE };
346	    return {
347	      offset: this._clampFinite(
348	        vignetteOpt.offset,
349	        DEFAULT_VIGNETTE.offset,
350	        0,
351	        4,
352	      ),
353	      darkness: this._clampFinite(
354	        vignetteOpt.darkness,
355	        DEFAULT_VIGNETTE.darkness,
356	        0,
357	        4,
358	      ),
359	    };
360	  }
