362	  private _createVignettePass(
363	    vignetteCfg: Required<VignetteOptions>,
364	  ): ShaderPass {
365	    const pass = new ShaderPass(VignetteShader);
366	    pass.uniforms.offset.value = vignetteCfg.offset;
367	    pass.uniforms.darkness.value = vignetteCfg.darkness;
368	    return pass;
369	  }
