371	  private _clampFinite(
372	    value: number | undefined,
373	    fallback: number,
374	    min: number,
375	    max: number,
376	  ): number {
377	    if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
378	    return Math.max(min, Math.min(max, value));
379	  }
