407	      return Array.isArray(mat)
408	        ? mat.every((x) => x.depthTest === false)
409	        : (mat as THREE.Material).depthTest === false;
410	    });
411	    console.log("[BLOOM:cache] rebuilt", {
412	      sceneMeshes: this._cachedSceneMeshes.length,
413	      nonBloomMeshes: this._cachedNonBloomMeshes.length,
414	      depthOffCount: depthOffMeshes.length,
415	      depthOff: depthOffMeshes.map((m) => ({
416	        name: m.name || `(uuid:${m.uuid.slice(0, 8)})`,
417	        renderOrder: m.renderOrder,
418	        materialType: Array.isArray(m.material) ? "multi" : m.material.type,
419	      })),
420	    });
421	  }
