424	    const meshes: THREE.Mesh[] = [];
425	    this._scene.traverse((obj) => {
426	      const mesh = obj as THREE.Mesh;
427	      if (!mesh.isMesh) return;
428	      meshes.push(mesh);
429	    });
430	    return meshes;
